// ─── File: DispatchDemo.java ───
// Compact Uber-like dispatch: geo index + matching (atomic claim) + payment.
// Each class below would be its own file in a real project.
package com.bank.dispatch;

import java.math.BigDecimal;
import java.util.logging.*;

public class DispatchDemo {

    private static final Logger log = Logger.getLogger("Dispatch");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        GeoIndex geo = new GeoIndex();
        // Drivers stream their current position into the in-memory geo index.
        geo.update("VAN-01", 28.6139, 77.2090);   // near the city centre
        geo.update("VAN-02", 28.6200, 77.2100);
        geo.update("VAN-03", 28.7000, 77.3000);   // far away

        MatchingEngine matcher = new MatchingEngine(geo);
        PaymentService payments = new PaymentService();

        // Rajesh requests a van at his pickup point.
        String driver = matcher.match("Rajesh", 28.6145, 77.2085);
        if (driver != null) {
            Trip trip = new Trip("TRIP-1001", "SAV2001", driver, new BigDecimal("450"));
            // Idempotent settlement: money moves rider → driver, bank takes commission.
            payments.settle(trip, "idem-TRIP-1001");
            payments.settle(trip, "idem-TRIP-1001");   // duplicate retry → ignored
        }

        // A second concurrent request must NOT get the same claimed van.
        String driver2 = matcher.match("Priya", 28.6150, 77.2088);
        log.info(() -> "Priya matched to: " + driver2 + " (never the same claimed van)");
    }
}

// ─── location/GeoIndex.java ───  in-memory current positions + radius query
class GeoIndex {
    private static final Logger log = Logger.getLogger("Dispatch");
    private final java.util.Map<String, double[]> positions = new java.util.concurrent.ConcurrentHashMap<>();
    private final java.util.Set<String> claimed = java.util.concurrent.ConcurrentHashMap.newKeySet();

    void update(String driverId, double lat, double lng) {
        positions.put(driverId, new double[]{lat, lng});   // latest position only (fast store)
    }

    // "find nearest AVAILABLE driver within radius" — the matching read path
    String nearestAvailable(double lat, double lng, double radiusKm) {
        return positions.entrySet().stream()
                .filter(e -> !claimed.contains(e.getKey()))                 // availability filter
                .filter(e -> haversineKm(lat, lng, e.getValue()[0], e.getValue()[1]) <= radiusKm)
                .min((a, b) -> Double.compare(
                        haversineKm(lat, lng, a.getValue()[0], a.getValue()[1]),
                        haversineKm(lat, lng, b.getValue()[0], b.getValue()[1])))
                .map(java.util.Map.Entry::getKey).orElse(null);
    }

    // atomic claim: prevents two riders grabbing the same driver (compare-and-set style)
    boolean claim(String driverId) {
        boolean ok = claimed.add(driverId);                 // add() is atomic on a concurrent set
        if (ok) log.info(() -> "claimed " + driverId);
        return ok;
    }

    private double haversineKm(double la1, double lo1, double la2, double lo2) {
        double dLat = Math.toRadians(la2 - la1), dLon = Math.toRadians(lo2 - lo1);
        double a = Math.sin(dLat / 2) * Math.sin(dLat / 2)
                + Math.cos(Math.toRadians(la1)) * Math.cos(Math.toRadians(la2))
                * Math.sin(dLon / 2) * Math.sin(dLon / 2);
        return 6371.0 * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    }
}

// ─── matching/MatchingEngine.java ───
class MatchingEngine {
    private static final Logger log = Logger.getLogger("Dispatch");
    private final GeoIndex geo;
    MatchingEngine(GeoIndex geo) { this.geo = geo; }

    String match(String rider, double pickupLat, double pickupLng) {
        double radius = 3.0;
        for (int attempt = 0; attempt < 3; attempt++) {          // expand radius if none found
            String candidate = geo.nearestAvailable(pickupLat, pickupLng, radius);
            if (candidate != null && geo.claim(candidate)) {      // atomic claim avoids double assign
                log.info(() -> rider + " matched to " + candidate + " within " + radius + "km");
                return candidate;
            }
            radius *= 2;                                          // widen search
        }
        log.warning(() -> "no van available for " + rider);
        return null;
    }
}

// ─── trip/Trip.java ───
class Trip {
    final String tripId, riderAccount, driverId;
    final BigDecimal fare;
    Trip(String tripId, String riderAccount, String driverId, BigDecimal fare) {
        this.tripId = tripId; this.riderAccount = riderAccount;
        this.driverId = driverId; this.fare = fare;
    }
}

// ─── payment/PaymentService.java ───  bank money movement + idempotency
class PaymentService {
    private static final Logger log = Logger.getLogger("Dispatch");
    private final java.util.Set<String> processed = java.util.concurrent.ConcurrentHashMap.newKeySet();

    void settle(Trip trip, String idempotencyKey) {
        if (!processed.add(idempotencyKey)) {                    // duplicate retry → no double charge
            log.warning(() -> "duplicate settlement ignored for " + idempotencyKey);
            return;
        }
        BigDecimal commission = trip.fare.multiply(new BigDecimal("0.20"));   // 20% bank cut
        BigDecimal driverPayout = trip.fare.subtract(commission);
        // debit rider, credit driver, credit bank commission (real impl: @Transactional ledger)
        log.info(() -> "SETTLE " + trip.tripId + ": debit " + trip.riderAccount + " Rs." + trip.fare
                + " → driver " + trip.driverId + " Rs." + driverPayout
                + ", bank commission Rs." + commission);
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
